    40  typedef struct AlarmState
    41  {
    42      uint32_t fire;
    43      bool     isRunning;
    44  } AlarmState;
    45
    46  static uint32_t     sAlarmNow;
    47  static AlarmState   sAlarmMilli;
    48  static AlarmState   sAlarmMicro;
    49  static uint32_t     sRandomState = 1;
    50  static uint8_t      sRadioTransmitPsdu[OT_RADIO_FRAME_MAX_SIZE];
    51  static otRadioFrame sRadioTransmitFrame = {.mPsdu = sRadioTransmitPsdu};
    52  static bool         sResetWasRequested  = false;
    53
    54  void FuzzerPlatformInit(void)
    55  {
    56      sRandomState = 1;
    57      sAlarmNow    = 0;
    58      memset(&sAlarmMilli, 0, sizeof(sAlarmMilli));
    59      memset(&sAlarmMicro, 0, sizeof(sAlarmMicro));
    60  }
    61
    62  void FuzzerPlatformProcess(otInstance *aInstance)
    63  {
    64      if (sAlarmMilli.isRunning || sAlarmMicro.isRunning)
    65      {
    66          uint32_t fire = UINT32_MAX;
    67
    68          if (sAlarmMilli.isRunning && fire > sAlarmMilli.fire)
    69          {
    70              fire = sAlarmMilli.fire;
    71          }
    72
    73          if (sAlarmMicro.isRunning && fire > sAlarmMicro.fire)
    74          {
    75              fire = sAlarmMicro.fire;
    76          }
    77
    78          sAlarmNow = fire;
    79
    80          if (sAlarmMilli.isRunning && sAlarmNow >= sAlarmMilli.fire)
    81          {
    82              sAlarmMilli.isRunning = false;
    83              otPlatAlarmMilliFired(aInstance);
    84          }
    85
    86  #if OPENTHREAD_CONFIG_PLATFORM_USEC_TIMER_ENABLE
    87          if (sAlarmMicro.isRunning && sAlarmNow >= sAlarmMicro.fire)
    88          {
    89              sAlarmMicro.isRunning = false;
    90              otPlatAlarmMicroFired(aInstance);
    91          }
    92  #endif
    93      }
    94  }
    95
    96  bool FuzzerPlatformResetWasRequested(void)
    97  {
    98      return sResetWasRequested;
    99  }
